# The image pool, catalogued. One dict per picture.
# f: file in pool/ poolB/ poolC/ · s: section · t: title · fx,fy: focal point (0-1) · z: tile zoom (fraction of the short side kept)
# shows · means · tool (what the code draws today) · poss (possibility) · bl (build-list numbers) · src (batch) · i (brand read off the dial, uncertain)
SECTIONS = [
  ("shine", "Shine", "Finishes that move under light. The tool draws a flat plate; watch.js holds grain, weave and brush patterns for the watch, none for the dial. The Finishes section's groove rule says how each would be drawn under one sun."),
  ("lume", "Lume at night", "Night shots. The whole watch becomes one glowing graphic: bezel, chapter ring, hands. This is the Day · Night switch in Next, and the notice when hands and markers glow differently."),
  ("cases", "Cases, lugs and bracelets", "Four cases in CASES, all round (field cushion 1939, diver SPB143, Emre's prototype, dress Calatrava); two bracelets on lugs, closed round a wrist since 4.94.18. No square, TV, tonneau or integrated case."),
  ("straps", "Leather and straps", "Leather in three tones per colour with a pore-and-crease grain; NATO in six stripe sets with a weave; buckle, keepers, taper. No stitch line, no suede nap, no rubber."),
  ("prep", "Dial preparation", "The makers' side: enamel on the firing mesh, stone blanks, a one-page spec sheet, a CAD render used as a brief. The proof-sheet idea, seen from where it is needed."),
  ("type", "Type and clock faces", "Clocks and watches where the type is the dial. Seventy-five open fonts in the tool, one per ring, upright or on the path; Michroma and Audiowide for the Eurostile look, Arimo for Helvetica's metrics. No word numerals, no numerals turned to the radius, no disc dial."),
  ("letter", "Lettering and classics", "How dial lettering is drawn, classic dials with their own numeral logic, and a cloisonné enamel at three stages. Text rings exist; hand lettering, a Breguet set and two colours in one ring do not."),
]
P = []
def a(f, s, t, shows, means, tool, poss, bl="", fx=0.5, fy=0.5, z=1.0, src="Reddit, batch 1", i=False):
    P.append(dict(f=f, s=s, t=t, shows=shows, means=means, tool=tool, poss=poss, bl=bl, fx=fx, fy=fy, z=z, src=src, i=i))

